<?php
declare(strict_types=1);namespace App\Services;use App\Support\Database;
final class WithdrawalService {
 public function __construct(private ?Database $db,private WalletService $wallets,private KycService $kyc,private DynamicFormService $forms,private NotificationService $notifications){}
 public function methods(int $countryId):array{return $this->db?->select('SELECT m.* FROM withdrawal_methods m JOIN withdrawal_method_countries c ON c.withdrawal_method_id=m.id WHERE c.country_id=? AND m.enabled=1 ORDER BY m.sort_order,m.name',[$countryId])??[];}
 public function method(int $countryId,int $id):?array{return $this->db?->one('SELECT m.* FROM withdrawal_methods m JOIN withdrawal_method_countries c ON c.withdrawal_method_id=m.id WHERE c.country_id=? AND m.id=? AND m.enabled=1',[$countryId,$id]);}
 public function quote(array $user,array $country,int $methodId,int $amount):array{if(!$this->kyc->canWithdraw($user,$country))throw new \RuntimeException('Identity verification is required before withdrawals are available.');$m=$this->method((int)$country['id'],$methodId);if(!$m||$amount<=0||$amount<(int)$m['minimum_amount_minor']||($m['maximum_amount_minor']!==null&&$amount>(int)$m['maximum_amount_minor']))throw new \RuntimeException('Withdrawal method or amount is unavailable.');$fee=$this->fee($amount,$m);$reserved=$m['fee_behavior']==='ADD_TO_DEBIT'?$amount+$fee:$amount;$payout=$amount-$fee;if($payout<0)throw new \RuntimeException('Invalid withdrawal fee.');return ['method'=>$m,'fee_minor'=>$fee,'reserved_amount_minor'=>$reserved,'payout_amount_minor'=>$payout];}
 public function submit(array $user,array $country,int $methodId,int $amount,array $values=[]):array{if(!$this->db)throw new \RuntimeException('Database unavailable.');$quote=$this->quote($user,$country,$methodId,$amount);$m=$quote['method'];$fields=$this->forms->definition($m['form_id']?(int)$m['form_id']:null);$this->forms->validate($fields,$values,[]);$wallet=$this->wallets->walletFor($user,$country);$ref='WDR-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(6)));$result=$this->db->transaction(function(Database $db)use($wallet,$user,$country,$m,$amount,$quote,$values,$fields,$ref){$reservation=$this->wallets->reserve((int)$wallet['id'],$quote['reserved_amount_minor'],'withdrawal','withdrawal',$ref);$snapshot=$this->forms->snapshot($m['form_id']?(int)$m['form_id']:null,'WITHDRAWAL');$db->execute('INSERT INTO withdrawal_requests(public_id,reference,user_id,wallet_id,country_id,currency_code,withdrawal_method_id,form_snapshot_id,method_snapshot,requested_amount_minor,fee_minor,payout_amount_minor,reserved_amount_minor,reservation_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[bin2hex(random_bytes(16)),$ref,$user['id'],$wallet['id'],$country['id'],$country['currency_code'],$m['id'],$snapshot,json_encode(['name'=>$m['name'],'instructions'=>$m['instructions'],'fee_type'=>$m['fee_type'],'fee_value'=>$m['fee_value'],'fee_behavior'=>$m['fee_behavior']]),$amount,$quote['fee_minor'],$quote['payout_amount_minor'],$quote['reserved_amount_minor'],$reservation['id']]);$id=(int)$db->pdo()->lastInsertId();foreach($values as$key=>$value){$field=array_values(array_filter($fields,fn($f)=>$f['field_key']===$key))[0]??null;if($field&&$field['field_type']!=='FILE')$db->execute('INSERT INTO withdrawal_submission_values(withdrawal_request_id,field_key,field_label,value_text) VALUES (?,?,?,?)',[$id,$key,$field['label'],is_array($value)?implode(',',array_map('strval',$value)):(string)$value]);}return ['id'=>$id,'reference'=>$ref];});$this->notifications->transactional((int)$user['id'],'withdrawal_submitted','Withdrawal request submitted','Funds have been reserved while your request is reviewed.',['url'=>'/dashboard/withdraw/'.$result['reference']]);return $result;}
 public function forUser(int $userId,int $page=1,int $perPage=20):array{if(!$this->db)return ['items'=>[],'total'=>0];$total=(int)$this->db->scalar('SELECT COUNT(*) FROM withdrawal_requests WHERE user_id=?',[$userId]);$offset=max(0,($page-1)*$perPage);$items=$this->db->select('SELECT w.*,m.name method_name FROM withdrawal_requests w JOIN withdrawal_methods m ON m.id=w.withdrawal_method_id WHERE w.user_id=? ORDER BY w.submitted_at DESC LIMIT '.(int)$offset.','.(int)$perPage,[$userId]);return ['items'=>$items,'total'=>$total];}
 public function findForUser(int $userId,string $reference):?array{return $this->db?->one('SELECT w.*,m.name method_name FROM withdrawal_requests w JOIN withdrawal_methods m ON m.id=w.withdrawal_method_id WHERE w.user_id=? AND w.reference=?',[$userId,$reference]);}
 public function values(int $id):array{return $this->db?->select('SELECT * FROM withdrawal_submission_values WHERE withdrawal_request_id=?',[$id])??[];}
 public function cancel(int $userId,string $reference):void{if(!$this->db)return;$this->db->transaction(function(Database $db)use($userId,$reference){$w=$db->lockForUpdate('SELECT * FROM withdrawal_requests WHERE user_id=? AND reference=?',[$userId,$reference]);if(!$w||$w['status']!=='PENDING')throw new \RuntimeException('This withdrawal can no longer be cancelled.');$this->wallets->release((int)$w['reservation_id']);$db->execute('UPDATE withdrawal_requests SET status="CANCELLED",updated_at=NOW() WHERE id=?',[$w['id']]);});}
 public function transition(int $id,int $adminId,string $action,string $reason='',string $note='',string $payoutReference=''):void{if(!$this->db)return;if($action==='REJECT'&&trim($reason)==='')throw new \InvalidArgumentException('A user-facing rejection reason is required.');$event=$this->db->transaction(function(Database $db)use($id,$adminId,$action,$reason,$note,$payoutReference){$w=$db->lockForUpdate('SELECT * FROM withdrawal_requests WHERE id=?',[$id]);if(!$w)throw new \RuntimeException('Withdrawal not found.');$map=['REVIEW'=>['PENDING','UNDER_REVIEW'],'APPROVE'=>['UNDER_REVIEW','PENDING'],'PROCESS'=>['APPROVED']];if(isset($map[$action])){if(!in_array($w['status'],$map[$action],true))throw new \RuntimeException('Invalid withdrawal state transition.');$status=['REVIEW'=>'UNDER_REVIEW','APPROVE'=>'APPROVED','PROCESS'=>'PROCESSING'][$action];$db->execute('UPDATE withdrawal_requests SET status=?,reviewed_at=NOW(),reviewed_by_user_id=?,admin_notes=?,updated_at=NOW() WHERE id=?',[$status,$adminId,$note,$id]);return ['user_id'=>(int)$w['user_id'],'reference'=>$w['reference'],'type'=>'withdrawal_'.strtolower($status),'title'=>'Withdrawal '.strtolower(str_replace('_',' ',$status)),'message'=>''];}if($action==='REJECT'){if(!in_array($w['status'],['PENDING','UNDER_REVIEW','APPROVED'],true))throw new \RuntimeException('This withdrawal cannot be rejected.');$this->wallets->release((int)$w['reservation_id']);$db->execute('UPDATE withdrawal_requests SET status="REJECTED",rejection_reason=?,admin_notes=?,reviewed_at=NOW(),reviewed_by_user_id=?,updated_at=NOW() WHERE id=?',[$reason,$note,$adminId,$id]);return ['user_id'=>(int)$w['user_id'],'reference'=>$w['reference'],'type'=>'withdrawal_rejected','title'=>'Withdrawal rejected','message'=>$reason];}if($action==='PAID'){if(!in_array($w['status'],['APPROVED','PROCESSING'],true))throw new \RuntimeException('Withdrawal is not ready to mark paid.');$ledger=$this->wallets->consume((int)$w['reservation_id'],'WITHDRAWAL','Manual withdrawal paid','withdrawal',(string)$w['id'],$adminId);$db->execute('UPDATE withdrawal_requests SET status="PAID",payout_reference=?,reviewed_at=NOW(),reviewed_by_user_id=?,completed_ledger_transaction_id=?,admin_notes=?,updated_at=NOW() WHERE id=?',[$payoutReference?:null,$adminId,$ledger['id'],$note,$id]);return ['user_id'=>(int)$w['user_id'],'reference'=>$w['reference'],'type'=>'withdrawal_paid','title'=>'Withdrawal paid','message'=>'Your withdrawal has been marked paid.'];}throw new \InvalidArgumentException('Unknown withdrawal action.');});try{$this->notifications->transactional($event['user_id'],$event['type'],$event['title'],$event['message'],['url'=>'/dashboard/withdraw/'.$event['reference']]);}catch(\Throwable){/* Financial state is committed before non-critical notification delivery. */}}
 public function queue(array $filters=[],int $page=1):array{if(!$this->db)return ['items'=>[],'total'=>0];$where=['1=1'];$p=[];foreach(['status'=>'w.status','country_id'=>'w.country_id','method_id'=>'w.withdrawal_method_id'] as $key=>$col)if(($filters[$key]??'')!==''){$where[]=$col.'=?';$p[]=$filters[$key];}if(($filters['q']??'')!==''){$where[]='(w.reference LIKE ? OR u.email LIKE ?)';$p[]='%'.$filters['q'].'%';$p[]='%'.$filters['q'].'%';}$sql=implode(' AND ',$where);$total=(int)$this->db->scalar('SELECT COUNT(*) FROM withdrawal_requests w JOIN users u ON u.id=w.user_id WHERE '.$sql,$p);$p[]=max(0,($page-1)*20);return ['items'=>$this->db->select('SELECT w.*,u.email,u.first_name,u.last_name,m.name method_name FROM withdrawal_requests w JOIN users u ON u.id=w.user_id JOIN withdrawal_methods m ON m.id=w.withdrawal_method_id WHERE '.$sql.' ORDER BY w.submitted_at DESC LIMIT ?,20',$p),'total'=>$total];}
 private function fee(int $amount,array $m):int{if($m['fee_type']==='NONE')return 0;if($m['fee_type']==='FIXED')return(int)$m['fee_value'];[$whole,$fraction]=array_pad(explode('.',(string)$m['fee_value'],2),2,'');$basis=(int)$whole*100+(int)str_pad(substr($fraction,0,2),2,'0');return intdiv($amount*$basis,10000);}
}
